import { GoogleGenAI } from "@google/genai";

/**
 * Simple in-memory cache to prevent redundant calls and handle 429s gracefully
 */
const responseCache: Record<string, string> = {
  priority: "",
  admin: "",
  strategy: ""
};

/**
 * Helper to call Gemini with exponential backoff for transient errors
 */
async function generateWithRetry(model: string, prompt: string, cacheKey: string, fallback: string, retries = 2, delay = 1000): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: model,
      contents: prompt,
      config: {
        temperature: 0.7,
        topP: 0.9,
      }
    });

    const text = response.text;
    if (text) {
      responseCache[cacheKey] = text;
      return text;
    }
    return responseCache[cacheKey] || fallback;
  } catch (error: any) {
    const errorMessage = error?.message || "";
    if (errorMessage.includes("429") || errorMessage.includes("quota")) {
      if (retries > 0) {
        await new Promise(resolve => setTimeout(resolve, delay));
        return generateWithRetry(model, prompt, cacheKey, fallback, retries - 1, delay * 2);
      }
      return responseCache[cacheKey] || fallback;
    }
    console.error(`Gemini API Error (${cacheKey}):`, error);
    return responseCache[cacheKey] || fallback;
  }
}

export const getPriorityInsights = async (history: any[], userName: string) => {
  const prompt = `
    Context: A Medical Representative (MR) named ${userName} is using a hospital pass booking system.
    System Rules:
    - 14 days without a pass: +5 priority points (High Need).
    - 7 days without a pass: +3 priority points.
    - Pass in last 3 days: -5 priority points (Cooldown - Lower Priority).
    - Missed entry (no-show): -10 points (Severe Penalty).

    User Recent History (last 3 apps): ${JSON.stringify(history)}

    Task: Write a 2-sentence encouraging insight for ${userName} regarding their "Field Intelligence v3.7" status. 
    Explain how their recent actions affect their upcoming lottery results.
    Tone: Professional, supportive, and data-driven.
  `;

  const defaultFallback = "Your priority is calculated based on recent visits and attendance reliability to ensure system fairness. Maintaining a consistent visit record helps optimize your rank.";

  return generateWithRetry('gemini-3-flash-preview', prompt, "priority", defaultFallback);
};

export const getDetailedLotteryStrategy = async (history: any[], stats: any, userName: string) => {
  const prompt = `
    Analyze this MR's (${userName}) lottery history and provide a "3.7 Professional Strategy":
    History: ${JSON.stringify(history)}
    Stats: ${JSON.stringify(stats)}

    Current System Logic:
    - Missed visits severely damage priority for 30 days.
    - Consistent attendance builds "Trust Factor" (weighted slightly in edge cases).
    - Cooldowns are strictly 3 days from the last pass DATE.

    Task: Provide 3 short, bulleted tips for ${userName} to maximize their "Pass Success Rate" in the next 7 days.
    Be extremely specific based on their data.
  `;

  return generateWithRetry('gemini-3-pro-preview', prompt, "strategy", "Focus on maintaining 100% attendance and target sessions with lower historical demand.");
};

export const getAdminBriefing = async (apps: any[], passes: any[], hospitalName: string) => {
  const prompt = `
    Context: You are an AI Logistics Analyst for ${hospitalName} (MedPass v3.7). 
    Today's Data: 
    - Total Applications: ${apps.length}
    - Passes Issued: ${passes.length}
    - Success Rate: ${apps.length > 0 ? ((passes.length / apps.length) * 100).toFixed(1) : 0}%

    Task: Provide a high-level summary of facility demand. Recommend if pass limits should be adjusted to manage lobby traffic or if the 'Auto-Lottery' schedule is optimal.
    Tone: Analytical and authoritative. Max 30 words.
  `;

  const defaultFallback = "Demand is stable. Current limits are sufficient to balance field access with facility operational capacity.";

  return generateWithRetry('gemini-3-flash-preview', prompt, "admin", defaultFallback);
};

