import { supabase } from './supabaseClient';

// Simple context for global notifications
export const FeedbackContext = createContext<{
  showFeedback: (msg: string, type?: 'success' | 'error') => void;
}>({ showFeedback: () => {} });

const FeedbackToast = ({ message, type, onClose }: { message: string, type: 'success' | 'error', onClose: () => void }) => {
  useEffect(() => {
    const timer = setTimeout(onClose, 4000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className="fixed bottom-6 right-6 z-[200] animate-in slide-in-from-right-10 fade-in duration-300">
      <div className={`flex items-center gap-3 px-6 py-4 rounded-2xl shadow-2xl border ${
        type === 'success' ? 'bg-white border-green-100 text-green-800' : 'bg-white border-red-100 text-red-800'
      }`}>
        {type === 'success' ? <CheckCircle2 className="h-6 w-6 text-green-500" /> : <AlertCircle className="h-6 w-6 text-red-500" />}
        <p className="font-bold text-sm">{message}</p>
        <button onClick={onClose} className="ml-2 p-1 hover:bg-slate-100 rounded-lg transition-all">
          <X className="h-4 w-4 text-slate-400" />
        </button>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [view, setView] = useState<'LOGIN' | 'DASHBOARD'>('LOGIN');
  const [role, setRole] = useState<UserRole>('MR');
  const [mobile, setMobile] = useState('');
  const [password, setPassword] = useState('');
  const [feedback, setFeedback] = useState<{ message: string, type: 'success' | 'error' } | null>(null);
  const [isLoggingIn, setIsLoggingIn] = useState(false);

  const autoRunLogs = useRef<Set<string>>(new Set());

  useEffect(() => {
    const session = storageService.getCurrentUser();
    if (session) { 
      setUser(session); 
      setView('DASHBOARD'); 
    }

    const automationInterval = setInterval(async () => {
      try {
        const now = new Date();
        const today = now.toLocaleDateString('en-CA');
        const currentTimeStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;
        const currentTimeNum = now.getHours() * 100 + now.getMinutes();

        const hospitals = await storageService.getHospitals();
        const allPasses = await storageService.getPasses();
        let hasPassChanges = false;

        const updatedPasses = allPasses.map(p => {
          if (p.entryStatus === 'expired' || p.entryStatus === 'ended') return p;
          if (p.passDate < today) {
            hasPassChanges = true;
            return { ...p, entryStatus: p.entryStatus === 'entered' ? 'ended' as const : 'expired' as const };
          }

          if (p.passDate === today) {
            const hosp = hospitals.find(h => h.id === p.hospitalId);
            if (!hosp) return p;
            const defaultTime = p.session === 'MORNING' ? '13:00' : '23:00';
            const configuredTimes = hosp.expiryTimes?.[p.session] || { issued: defaultTime, active: defaultTime };
            const convertToNum = (t: string) => parseInt(t.replace(':', ''));
            const issuedExpiryNum = convertToNum(configuredTimes.issued);
            const activeEndNum = convertToNum(configuredTimes.active);

            if (p.entryStatus === 'not_entered' && currentTimeNum >= issuedExpiryNum) {
              hasPassChanges = true;
              return { ...p, entryStatus: 'expired' as const };
            }
            if (p.entryStatus === 'entered' && currentTimeNum >= activeEndNum) {
              hasPassChanges = true;
              return { ...p, entryStatus: 'ended' as const };
            }
          }
          return p;
        });

        if (hasPassChanges) {
          await storageService.savePasses(updatedPasses);
        }

        for (const hosp of hospitals) {
          if (!hosp.isActive || !hosp.autoLotteryEnabled) continue;
          const sessions: SessionType[] = ['MORNING', 'EVENING', 'FULL_DAY'];
          for (const sess of sessions) {
            const isEnabled = hosp.autoLotteryEnabled?.[sess];
            const triggerTime = hosp.autoLotteryTimes?.[sess];
            if (isEnabled && triggerTime && currentTimeStr >= triggerTime) {
              const logKey = `${hosp.id}-${today}-${sess}`;
              if (!autoRunLogs.current.has(logKey)) {
                const result = await lotteryService.runLottery(hosp.id, sess);
                if (result.success || result.message.includes("already executed") || result.message.includes("No eligible")) {
                  autoRunLogs.current.add(logKey);
                }
              }
            }
          }
        }
      } catch (err) {
        console.error("Automation error:", err);
      }
    }, 60000);

    return () => clearInterval(automationInterval);
  }, []);

  const showFeedback = (message: string, type: 'success' | 'error' = 'success') => {
    setFeedback({ message, type });
  };

  const handleLogin = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!mobile || !password) {
      showFeedback("Please enter both ID and Password.", "error");
      return;
    }
    setIsLoggingIn(true);

    try {
      if (role === 'MR') {
        const { data, error } = await supabase
          .from('profiles')
          .select('*, mrs(*, pharma_companies(name))')
          .eq('mobile_number', mobile)
          .eq('password', password)
          .eq('role', 'MR')
          .single();

        if (data) {
          const u: AuthUser = { 
            id: data.id, 
            fullName: data.full_name, 
            role: 'MR', 
            loginId: data.mobile_number,
            mobileNumber: data.mobile_number,
            companyName: (data.mrs as any)?.pharma_companies?.name || 'Pharma'
          };
          storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
          showFeedback(`Welcome back, ${u.fullName}!`);
        } else {
          showFeedback("Invalid MR credentials.", 'error');
        }
      } else {
        let dbRole: string = role;
        if (role === 'ADMIN') dbRole = 'HOSPITAL_ADMIN';
        if (role === 'COMPANY_ADMIN') dbRole = 'COMPANY';

        const { data, error } = await supabase
          .from('profiles')
          .select('*')
          .eq('role', dbRole)
          .eq('password', password)
          .or(`mobile_number.eq.${mobile},full_name.eq.${mobile}`)
          .single();

        if (data) {
          const u: AuthUser = { 
            id: data.id,
            role: role, 
            fullName: data.full_name, 
            hospitalId: data.hospital_id,
            mobileNumber: data.mobile_number,
            companyId: data.role === 'COMPANY' ? data.id : undefined 
          };
          storageService.setCurrentUser(u); setUser(u); setView('DASHBOARD');
          showFeedback(`Logged in as ${data.full_name}`);
        } else {
          showFeedback(`Invalid ${role} credentials.`, 'error');
        }
      }
    } catch (err) {
      showFeedback("Authentication failed. Connection error.", 'error');
    } finally {
      setIsLoggingIn(false);
    }
  };

  const handleLogout = () => {
    storageService.clearSession();
    setUser(null);
    setView('LOGIN');
    showFeedback("Successfully logged out.");
  };

  const quickLogin = (r: UserRole, phone = '', pass = '') => { 
    setRole(r); 
    setMobile(phone);
    setPassword(pass);
  };

  const renderDashboard = () => {
    if (!user) return null;
    switch (user.role) {
      case 'MR': return <MRDashboard user={user as any} />;
      case 'ADMIN': return <AdminDashboard user={user as any} />;
      case 'SECURITY': return <SecurityView />;
      case 'SUPER_ADMIN': return <SuperAdminDashboard />;
      case 'COMPANY_ADMIN': return <CompanyAdminDashboard user={user} />;
      default: return <div>Role not recognized</div>;
    }
  };

  return (
    <FeedbackContext.Provider value={{ showFeedback }}>
      {feedback && <FeedbackToast message={feedback.message} type={feedback.type} onClose={() => setFeedback(null)} />}

      {view === 'LOGIN' ? (
        <div className="min-h-screen bg-slate-900 flex flex-col md:flex-row">
          {/* Hero Section */}
          <div className="flex-1 p-12 flex flex-col justify-center bg-gradient-to-br from-indigo-900 via-slate-900 to-indigo-950 text-white relative overflow-hidden">
             <div className="absolute top-0 right-0 w-96 h-96 bg-indigo-500 rounded-full blur-[120px] opacity-20 -translate-y-1/2 translate-x-1/2"></div>
             <div className="absolute bottom-0 left-0 w-64 h-64 bg-indigo-400 rounded-full blur-[100px] opacity-10"></div>

             <div className="relative z-10 space-y-8 max-w-xl">
                <div className="flex items-center gap-3">
                   <div className="p-3 bg-white/10 backdrop-blur-md rounded-2xl border border-white/20 shadow-xl">
                      <HospitalIcon className="h-8 w-8 text-indigo-400" />
                   </div>
                   <h1 className="text-4xl font-black tracking-tighter">MedPass</h1>
                </div>

                <div className="space-y-4">
                   <h2 className="text-6xl font-black leading-none tracking-tighter">Professional Field Intelligence v3.7</h2>
                   <p className="text-indigo-200 text-lg font-medium leading-relaxed">
                      Advanced hospital access orchestration, real-time gate synchronization, and AI-driven lottery optimization for the medical field.
                   </p>
                </div>

                <div className="grid grid-cols-2 gap-4 pt-6">
                   <div className="bg-white/5 border border-white/10 p-4 rounded-3xl backdrop-blur-sm">
                      <Zap className="h-6 w-6 text-indigo-400 mb-2" />
                      <p className="text-xs font-black uppercase tracking-widest text-white/60">Live Lottery</p>
                      <p className="text-sm font-bold mt-1">Instant Results</p>
                   </div>
                   <div className="bg-white/5 border border-white/10 p-4 rounded-3xl backdrop-blur-sm">
                      <Shield className="h-6 w-6 text-indigo-400 mb-2" />
                      <p className="text-xs font-black uppercase tracking-widest text-white/60">Security Gate</p>
                      <p className="text-sm font-bold mt-1">QR Synchronization</p>
                   </div>
                </div>

                <div className="flex items-center gap-2 pt-12">
                   <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
                   <p className="text-[10px] font-black uppercase tracking-[0.3em] text-white/40">System Node: Operational 100%</p>
                </div>
             </div>
          </div>

          {/* Login Form Section */}
          <div className="w-full md:w-[480px] bg-white p-8 md:p-16 flex flex-col justify-center shadow-2xl z-20">
            <div className="mb-10 text-center">
              <h3 className="text-3xl font-black text-slate-800 tracking-tight">Access Terminal</h3>
              <p className="text-slate-400 text-sm font-bold mt-2 uppercase tracking-widest">Identify to continue</p>
            </div>

            <form onSubmit={handleLogin} className="space-y-6">
              <div className="flex bg-slate-100 p-1.5 rounded-2xl gap-1 overflow-x-auto">
                {(['MR', 'ADMIN', 'SECURITY', 'COMPANY_ADMIN', 'SUPER_ADMIN'] as UserRole[]).map((r) => (
                  <button 
                    key={r}
                    type="button"
                    onClick={() => setRole(r)}
                    className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all whitespace-nowrap ${role === r ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:bg-slate-200'}`}
                  >
                    {r.replace('_', ' ')}
                  </button>
                ))}
              </div>

              <div className="space-y-4">
                <div className="relative">
                  <User className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-slate-400" />
                  <input 
                    type="text" 
                    placeholder={role === 'MR' ? "Login ID (Mobile)" : "Identity ID"}
                    value={mobile}
                    onChange={(e) => setMobile(e.target.value)}
                    className="w-full pl-12 pr-6 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl font-bold focus:border-indigo-500 outline-none transition-all"
                  />
